const {chromium}=require('playwright');const assert=require('node:assert/strict');const fs=require('node:fs');
(async()=>{fs.mkdirSync('work/screenshots',{recursive:true});const browser=await chromium.launch({headless:true,args:['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--no-sandbox']});
const errors=[];const context=await browser.newContext({viewport:{width:1440,height:1100}});const page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text());});
await page.goto('http://127.0.0.1:8765/',{waitUntil:'networkidle'});assert.equal(await page.locator('#renderError').isVisible(),false,'WebGL initializes');await page.screenshot({path:'work/screenshots/01-desktop.png',fullPage:true});
await page.locator('#start').click();await page.keyboard.down('ArrowUp');await page.waitForFunction(()=>document.querySelector('#phaseLabel').textContent.includes('螺旋翻转'),{},{timeout:40000});await page.waitForFunction(()=>parseInt(document.querySelector('#roll').textContent)>75,{},{timeout:20000});await page.locator('#gameShell').screenshot({path:'work/screenshots/02-corkscrew.png'});
await page.waitForFunction(()=>document.querySelector('#phaseLabel').textContent.includes('倒扣出轨'),{},{timeout:20000});await page.keyboard.up('ArrowUp');await page.locator('#gameShell').screenshot({path:'work/screenshots/03-inverted.png'});await page.keyboard.down('KeyE');
let holding=false,terminal='',liftShot=false;const deadline=Date.now()+45000;
while(Date.now()<deadline){const ui=await page.evaluate(()=>({phase:document.querySelector('#phaseLabel').textContent,h:parseFloat(document.querySelector('#height').textContent),v:parseFloat(document.querySelector('#descent').textContent),roll:parseInt(document.querySelector('#roll').textContent),title:document.querySelector('#overlayTitle').textContent,visible:!document.querySelector('#overlay').hidden}));
if(ui.visible){terminal=ui.title;break;}
const fire=ui.phase.includes('倒扣出轨')&&ui.roll<14&&ui.v>Math.sqrt(10*ui.h+4);
if(fire&&!holding){await page.keyboard.down('ArrowUp');holding=true;}if(!fire&&holding){await page.keyboard.up('ArrowUp');holding=false;}
if(fire&&!liftShot&&ui.h>8){liftShot=true;await page.locator('#gameShell').screenshot({path:'work/screenshots/04-jet-recovery.png'});}
await page.waitForTimeout(40);
}
await page.keyboard.up('ArrowUp');await page.keyboard.up('KeyE');console.log('BROWSER PILOT',terminal);await page.screenshot({path:'work/screenshots/05-result.png',fullPage:true});assert.match(terminal,/落稳了/,'real browser pilot completes course');assert.match(await page.locator('#best').textContent(),/PTS/,'record saved');
await page.reload({waitUntil:'networkidle'});assert.match(await page.locator('#best').textContent(),/PTS/,'record persists after reload');await page.locator('#start').click();await page.keyboard.down('ArrowUp');await page.waitForTimeout(500);await page.locator('#pause').click();const speed=await page.locator('#speed').textContent();await page.waitForTimeout(300);assert.equal(await page.locator('#speed').textContent(),speed,'pause holds simulation');await page.locator('#start').click();await page.keyboard.up('ArrowUp');await page.locator('#restart').click();assert.match(await page.locator('#overlayTitle').textContent(),/把世界/,'restart returns to starting grid');
const mobile=await browser.newContext({viewport:{width:430,height:932},isMobile:true,hasTouch:true,deviceScaleFactor:1});const phone=await mobile.newPage();phone.on('pageerror',e=>errors.push(e.message));await phone.goto('http://127.0.0.1:8765/',{waitUntil:'networkidle'});assert.equal(await phone.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true,'mobile no horizontal overflow');console.log('MOBILE INPUT',await phone.evaluate(()=>({coarse:matchMedia('(pointer:coarse)').matches,touch:navigator.maxTouchPoints})));await phone.screenshot({path:'work/screenshots/06-mobile.png',fullPage:true});await phone.locator('#start').click();const gas=await phone.locator('[data-control="gas"]').boundingBox(),assist=await phone.locator('[data-control="assist"]').boundingBox();assert.ok(gas&&assist,'touch controls visible');const cdp=await mobile.newCDPSession(phone);await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:gas.x+gas.width/2,y:gas.y+gas.height/2,id:1},{x:assist.x+assist.width/2,y:assist.y+assist.height/2,id:2}]});await phone.waitForTimeout(600);assert.equal(await phone.locator('.touch-controls .pressed').count(),2,'multi-touch gas and assist both held');assert.ok(parseInt(await phone.locator('#speed').textContent())>0,'touch throttle accelerates');await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});assert.equal(await phone.locator('.touch-controls .pressed').count(),0,'touch release clears both');await phone.locator('#pause').click();await phone.setViewportSize({width:932,height:430});await phone.screenshot({path:'work/screenshots/07-mobile-landscape.png',fullPage:true});
assert.deepEqual(errors,[],'no browser JavaScript errors');console.log('PASS WebGL desktop, whole gameplay, pause, restart, persistence, phone layout and multi-touch');await browser.close();})().catch(e=>{console.error(e);process.exit(1);});
